{"path":"server.js","content":"import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const dbPath = process.env.DB_PATH || './data/workboard.sqlite';
if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
const page = readFileSync(new URL('./public/index.html', import.meta.url));

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

async function readJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 65536) throw new Error('Request too large');
  }
  return JSON.parse(body);
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') {
      return json(res, 200, { status: 'ok' });
    }
    if (req.method === 'GET' && path === '/api/projects') {
      return json(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY id').all());
    }
    if (req.method === 'POST' && path === '/api/projects') {
      let input;
      try { input = await readJson(req); }
      catch { return json(res, 400, { error: 'Invalid JSON request' }); }
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return json(res, 201, { id: Number(result.lastInsertRowid), name });
    }
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(match[1]);
      return project ? json(res, 200, project) : json(res, 404, { error: 'Project not found' });
    }
    if (req.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path))) {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(page);
    }
    return json(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    return json(res, 500, { error: 'Unable to complete request' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}
"}

{"path":"public/index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 0; background: #f4f6fa; color: #182337; }
    main { max-width: 760px; margin: 48px auto; padding: 24px; }
    h1 { overflow-wrap: anywhere; }
    form, .project-row { background: white; border: 1px solid #cdd4df; border-radius: 8px; padding: 20px; margin: 16px 0; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input { font: inherit; padding: 10px; border: 1px solid #66758c; border-radius: 4px; max-width: 100%; box-sizing: border-box; }
    button { font: inherit; background: #2457b5; color: white; border: 0; border-radius: 4px; padding: 10px 16px; cursor: pointer; }
    button:focus-visible, input:focus-visible { outline: 3px solid #ed9b00; outline-offset: 3px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .project-row span { overflow-wrap: anywhere; min-width: 0; }
    .project-row button { flex-shrink: 0; }
    [role="alert"] { color: #a21717; margin-top: 12px; }
    @media (max-width: 480px) { main { margin: 12px auto; padding: 16px; } form button { margin-top: 12px; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.getElementById('app');
    function element(tag, text) {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      return node;
    }
    async function request(path, options) {
      const response = await fetch(path, options);
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || 'Unable to complete request');
      return body;
    }
    function showError(message) {
      let alert = app.querySelector('[role="alert"]');
      if (!alert) {
        alert = element('div');
        alert.setAttribute('role', 'alert');
        app.append(alert);
      }
      alert.textContent = message;
    }
    function projectRow(project) {
      const row = element('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => { location.href = '/projects/' + project.id; });
      row.append(element('span', project.name), open);
      return row;
    }
    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        const back = element('button', 'Projects');
        back.addEventListener('click', () => { location.href = '/'; });
        app.append(back);
        const project = await request('/api/projects/' + match[1]);
        app.prepend(element('h1', project.name));
        document.title = project.name + ' — Workboard';
        return;
      }
      app.append(element('h1', 'Workboard'));
      const form = element('form');
      const label = element('label', 'Project name');
      label.htmlFor = 'project-name';
      const input = element('input');
      input.id = 'project-name';
      input.name = 'name';
      input.type = 'text';
      const create = element('button', 'Create project');
      create.type = 'submit';
      form.append(label, input, create);
      const list = element('section');
      list.setAttribute('aria-label', 'Projects');
      app.append(form, list);
      form.addEventListener('submit', async event => {
        event.preventDefault();
        if (!input.value.trim()) return showError('Project name is required');
        create.disabled = true;
        try {
          const project = await request('/api/projects', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name: input.value })
          });
          list.append(projectRow(project));
          input.value = '';
          app.querySelector('[role="alert"]')?.remove();
          input.focus();
        } catch (error) { showError(error.message); }
        finally { create.disabled = false; }
      });
      for (const project of await request('/api/projects')) list.append(projectRow(project));
    }
    render().catch(error => showError(error.message));
  </script>
</body>
</html>
"}

{"path":"test/server.test.js","content":"import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';

 test('project validation, ordering, routes, and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const reservation = net.createServer();
  await new Promise(resolve => reservation.listen(0, '127.0.0.1', resolve));
  const port = reservation.address().port;
  await new Promise(resolve => reservation.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'pipe']
    });
    let errors = '';
    child.stderr.on('data', chunk => { errors += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      if (child.exitCode !== null) throw new Error(errors);
      try {
        const response = await fetch(base + '/health');
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch { await new Promise(resolve => setTimeout(resolve, 25)); }
    }
    throw new Error('Server did not start: ' + errors);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = new Promise(resolve => child.once('exit', resolve));
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(base + '/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name })
    });
  }
  try {
    await start();
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), []);
    for (const name of ['', '   ', '\t\n']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.match((await response.json()).error, /Project name is required/);
    }
    const response = await create('  First project  ');
    assert.equal(response.status, 201);
    const first = await response.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('Second project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await fetch(base + '/api/projects/' + first.id)).json(), first);
    const html = await (await fetch(base + '/')).text();
    assert.match(html, /Workboard/);
    assert.match(html, /Project name/);
    assert.match(html, /Create project/);
    assert.match(html, /Open project/);
    assert.match(html, /project-row/);
    assert.equal((await fetch(base + '/projects/' + first.id)).status, 200);
    assert.equal((await fetch(base + '/api/projects/999999')).status, 404);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await fetch(base + '/api/projects/' + first.id)).json(), first);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
"}
